import express from 'express';
import dotenv from 'dotenv';
import Database from 'better-sqlite3';
import fs from 'fs';
import Twilio from 'twilio';
import { Resend } from 'resend';

dotenv.config();

const app = express();
app.use(express.json());

if (!fs.existsSync('./data')) fs.mkdirSync('./data');
const db = new Database('./data/reviewpilot.db');
db.exec(fs.readFileSync('./db.sql', 'utf8'));

const DRY = !process.env.TWILIO_SID || !process.env.RESEND_KEY;
const twilio = DRY ? null : Twilio(process.env.TWILIO_SID, process.env.TWILIO_TOKEN);
const resend = DRY ? null : new Resend(process.env.RESEND_KEY);
console.log(DRY ? 'DRY RUN — nothing will actually send' : 'LIVE mode');

// ---------- Health ----------
app.get('/', (_req, res) => res.json({ ok: true, dry: DRY }));

// ---------- Clients ----------
app.post('/clients', (req, res) => {
  const { name, review_link, send_sms = 1, send_email = 1 } = req.body;
  if (!name || !review_link) {
    return res.status(400).json({ error: 'name and review_link required' });
  }
  const info = db.prepare(
    'INSERT INTO clients (name, review_link, send_sms, send_email) VALUES (?, ?, ?, ?)'
  ).run(name, review_link, send_sms ? 1 : 0, send_email ? 1 : 0);
  res.json({ id: info.lastInsertRowid });
});

app.get('/clients', (_req, res) => {
  res.json(db.prepare('SELECT * FROM clients ORDER BY id DESC').all());
});

// ---------- Jobs ----------
// POST a completed job -> schedules a review request N hours later
app.post('/jobs', (req, res) => {
  const {
    client_id,
    customer_name,
    customer_phone,
    customer_email,
    delay_hours = 3
  } = req.body;

  if (!client_id) return res.status(400).json({ error: 'client_id required' });
  const client = db.prepare('SELECT * FROM clients WHERE id = ?').get(client_id);
  if (!client) return res.status(404).json({ error: 'Client not found' });

  const send_after = Date.now() + delay_hours * 3600 * 1000;
  const info = db.prepare(
    'INSERT INTO jobs (client_id, customer_name, customer_phone, customer_email, send_after) VALUES (?, ?, ?, ?, ?)'
  ).run(client_id, customer_name || null, customer_phone || null, customer_email || null, send_after);

  res.json({ id: info.lastInsertRowid, send_after });
});

app.get('/jobs', (_req, res) => {
  res.json(db.prepare('SELECT * FROM jobs ORDER BY id DESC LIMIT 100').all());
});

// ---------- Job Processing Loop (every 60s) ----------
setInterval(async () => {
  const now = Date.now();
  const jobs = db.prepare(
    'SELECT * FROM jobs WHERE sent = 0 AND send_after <= ?'
  ).all(now);

  for (const job of jobs) {
    const client = db.prepare('SELECT * FROM clients WHERE id = ?').get(job.client_id);
    if (!client || !client.active) {
      db.prepare('UPDATE jobs SET sent = 1, sent_at = ? WHERE id = ?')
        .run(new Date().toISOString(), job.id);
      continue;
    }

    const message = `Hi ${job.customer_name || 'there'}, thanks for choosing ${client.name}! ` +
      `If we did a good job, a quick Google review means the world: ${client.review_link}`;

    try {
      if (client.send_sms && job.customer_phone) {
        if (DRY) {
          console.log(`[DRY SMS] -> ${job.customer_phone}: ${message}`);
        } else {
          await twilio.messages.create({
            body: message,
            from: process.env.TWILIO_FROM,
            to: job.customer_phone
          });
          console.log(`SMS sent to ${job.customer_phone}`);
        }
      }

      if (client.send_email && job.customer_email) {
        if (DRY) {
          console.log(`[DRY EMAIL] -> ${job.customer_email}: ${message}`);
        } else {
          await resend.emails.send({
            from: process.env.RESEND_FROM,
            to: job.customer_email,
            subject: `How did we do, ${job.customer_name || 'friend'}?`,
            text: message
          });
          console.log(`Email sent to ${job.customer_email}`);
        }
      }

      db.prepare('UPDATE jobs SET sent = 1, sent_at = ? WHERE id = ?')
        .run(new Date().toISOString(), job.id);
    } catch (err) {
      console.error(`Job ${job.id} failed:`, err.message);
    }
  }
}, 60_000);

// ---------- Start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`ReviewPilot running on http://localhost:${PORT}`);
});
```

